import math

def is_prime(n):
    """Checks if n is a positive prime number."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def power(base, exp):
    """Calculates base^exp, handling integer constraints for prime P."""
    # We are looking for P to be a positive prime integer.
    if exp == 0:
        return 1
    if base == 0:
        return 0 if exp > 0 else float('inf') # Should not happen for prime P

    if exp > 0:
        return base ** exp

    # exp < 0
    if base == 1:
        return 1
    if base == -1:
        return 1 if exp % 2 == 0 else -1
    # If base is not 1 or -1, and exp is negative, base^exp is not an integer.
    return None # Indicates non-integer result

def calculate_P(x, y, z):
    """Calculates P = y^x z^y x^z and checks if it's a positive prime."""
    # Check for integer results first
    Tx = power(y, x)
    Ty = power(z, y)
    Tz = power(x, z)

    if Tx is None or Ty is None or Tz is None:
        return None # P is not an integer

    P = Tx * Ty * Tz

    # Check if P is a positive prime
    if P > 0 and is_prime(P):
        return P
    return None

